[
  {
    "kind": "narration",
    "text": "Wren tries to discuss the dawn patrol with Ash, but Ash seems preoccupied.",
    "cited_fact_keys": ["attempt:communicate", "attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "\"Dawn patrol passed at first light.\" Ash informs Wren, his voice distant.",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "de4ead3f-c2af-4267-9c89-69479c98df27"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash about the dawn patrol, but Ash remains silent, waiting.",
    "cited_fact_keys": ["attempt:communicate", "attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "\"Tell Wren about the mill,\" Ash finally speaks.",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "02d6e032-9200-47e0-aaf4-9bb20bfacc19"
  }
]

[
  {
    "kind": "narration",
    "cited_fact_keys": ["attempt:communicate"],
    "text": "Wren tries to engage Ash in conversation about the dawn patrol."
  },
  {
    "kind": "narration",
    "cited_fact_keys": ["attempt:wait"],
    "text": "Meanwhile, Ash patiently waits."
  },
  {
    "kind": "narration",
    "cited_fact_keys": ["reaction:1"],
    "text": "Ash discusses the mill with Wren."
  }
]

[
  {
    "kind": "narration",
    "text": "Wren tries to communicate with Ash about their dawn patrol plans.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Ash patiently waits for Wren to finish.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  }
]

[
  {
    "kind": "narration",
    "text": "The sun begins to rise, painting the sky with hues of orange and pink.",
    "cited_fact_keys": [],
    "speaker_id": null
  },
  {
    "kind": "action",
    "text": "Wren, standing at the edge of the cliff, waits patiently.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "narration",
    "text": "Ash, nearby, watches Wren intently.",
    "cited_fact_keys": [],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "Ash: Wren, are you ready for the dawn patrol?",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": "fb6f3a4e-e862-4d44-a833-7ff9fa68cbaa"
  },
  {
    "kind": "action",
    "text": "Ash attempts to communicate with Wren about the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "narration",
    "text": "Wren, still as a statue, does not respond.",
    "cited_fact_keys": [],
    "speaker_id": null
  },
  {
    "kind": "narration",
    "text": "Ash looks at Wren, concern etched on their face.",
    "cited_fact_keys": [],
    "speaker_id": null
  },
  {
    "kind": "narration",
    "text": "The sun continues its ascent, casting long shadows across the landscape.",
    "cited_fact_keys": [],
    "speaker_id": null
  }
]

[
  {
    "kind": "narration",
    "text": "Wren waits.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "action",
    "text": "Ash tries to get Wren's attention.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "Ash: Hey, Wren. We've got a dawn patrol coming up.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": "fb6f3a4e-e862-4d44-a833-7ff9fa68cbaa"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren waits patiently, her eyes scanning the horizon.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Ash attempts to communicate with Wren about the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "text": "Wren says to Ash: \"The mill road is clear.\"",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "0b80dfc6-92e3-4fc2-a9ac-c364f9ca2d07"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren waits patiently, his gaze fixed on the horizon.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Ash attempts to engage Wren in conversation, bringing up the topic of the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Wren, breaking his silence, speaks to Ash about the lamps.",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "8d7ee400-df18-435e-bee6-aa085a855176"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'Where is the mill?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "'Past the bridge, second left.'",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "4843ee7e-4861-4d7b-a067-7c1557b60fe4"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash about the mill stores.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits patiently.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"Grain and oilskins.\" Ash responds to Wren.",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "9a6851da-43ee-480a-a459-0c3e77a2465f"
  }
]

[
  {
    "kind": "narration",
    "text": "Ash waits patiently.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Wren tries to engage Ash in conversation.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "595816fb-b269-43b6-8da0-6a8c26dd55fd",
    "text": "\"Old Marlow, if the lamp is still lit.\" Ash responds to Wren.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking if the stalls are open yet.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash, who has been waiting patiently, responds to Wren's query.",
    "cited_fact_keys": ["attempt:wait", "reaction:1"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "c804a210-3087-4ffe-80fd-5890e817f011",
    "text": "\"Stalls open at second bell.\"",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Ash stood still, his eyes fixed on the horizon, waiting.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "action",
    "text": "Meanwhile, Wren tried to catch Ash's attention, eager to discuss their dawn patrol plans.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  }
]

[
  {
    "kind": "narration",
    "text": "Marlow and Wren attempt to communicate with Ash, each with their own messages.",
    "cited_fact_keys": ["attempt:communicate", "attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "Marlow turns to Wren, 'Aye, and mind the loose stones past the bridge.'",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "beb03d24-74c7-467d-9cc3-744e2a9f83bf"
  },
  {
    "kind": "dialogue",
    "text": "Ash chimes in, 'Dawn bell means the first stalls are opening.'",
    "cited_fact_keys": ["reaction:2"],
    "speaker_id": "fe1afce1-2f18-4100-9a4b-28b70af800a8"
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Ash patiently waits.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  }
]

[
  {
    "kind": "narration",
    "text": "Ash waits patiently, his gaze fixed on the horizon.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Wren attempts to engage Ash in conversation, trying to discuss the upcoming dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Marlow, ever observant, watches the exchange between Ash and Wren.",
    "cited_fact_keys": ["attempt:observe"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "0bba4d24-88b9-4543-8d77-f7117260225f",
    "text": "Dawn bell means the market's waking.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, trying to discuss their plans for the road ahead.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash, however, is preoccupied and waits for Wren to finish.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "5f0d1e47-a6f4-4cf2-83bd-4b54d5d0be60",
    "text": "Dawn bell means the market is waking early today, so hurry down with coin and basket before the best bread and freshest fish are gone from the stalls.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'Is the old bridge safe to cross?'",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "'No.', Ash responds curtly.",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "17f37dc2-cf4c-4730-b0b8-d13bdf28dd44"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'What news from the mill, Ash?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "4b135b1c-48da-4a54-bdb2-5743b141d486",
    "text": "'It's still standing, unless someone's moved it.' Ash replies.",
    "cited_fact_keys": ["reaction:1"]
  }
]
